use serde_json::json;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = json!({});

    for row in input.as_array().unwrap() {
        let mut sum = 0;
        for (key, value) in row.as_array().unwrap().iter() {
            sum += value.as_i64().unwrap();
        }

        result = json!({
            "key": key,
            "value": sum
        }).into();
    }

    result = json!({
        "rows": result
    }).into();

    result
}
